def _iter_render(
    self, tokens: Iterable[Dict[str, Any]], state: BlockState
) -> Iterable[Dict[str, Any]]:
    for tok in tokens:
        if 'children' in tok:
            children = self._iter_render(tok['children'], state)
            tok['children'] = list(children)
        elif 'text' in tok:
            text = tok.pop('text')
            # process inline text
            tok['children'] = self.inline(text.strip(), state.env)
        yield tok

actions.new_string:
def _iter_render(
    self, tokens: Iterable[Dict[str, Any]], state: BlockState
) -> Iterable[Dict[str, Any]]:
    for tok in tokens:
        if 'children' in tok:
            children = self._iter_render(tok['children'], state)
            tok['children'] = list(children)
        elif 'text' in tok:
            text = tok.pop('text')
            # process inline text
            # Use rstrip() instead of strip() to preserve leading whitespace
            tok['children'] = self.inline(text.rstrip(), state.env)
        yield tok
